 INSERT INTO ops_api_atomic_transport_bb0bd0ce.payload_parts(ordinal,payload) VALUES (4,$ops_compact_part_4$erence'', coalesce(a.application_reference, a.default_application_reference),\n        ''mailbox'', a.mailbox,\n        ''brp_ediel_id'', a.brp_ediel_id,\n        ''is_active'', a.is_active\n      ) order by a.environment, a.id)\n      from public.ediel_actor_settings a\n      where a.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', r.id,\n        ''environment'', r.environment,\n        ''route_type'', r.route_type,\n        ''sender_ediel_id'', r.sender_ediel_id,\n        ''sender_subaddress'', coalesce(r.sender_sub_address, r.sender_subaddress),\n        ''receiver_ediel_id'', r.receiver_ediel_id,\n        ''receiver_subaddress'', coalesce(r.receiver_sub_address, r.receiver_subaddress),\n        ''mailbox_id'', r.mailbox_id,\n        ''transport_profile_id'', r.transport_profile_id,\n        ''certificate_id'', r.certificate_id,\n        ''receiver_certificate_id'', r.receiver_certificate_id,\n        ''is_active'', r.is_active,\n        ''is_enabled'', r.is_enabled\n      ) order by r.environment, r.id)\n      from public.ediel_route_profiles r\n      where r.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', m.id,\n        ''environment'', m.environment,\n        ''mailbox_name'', m.mailbox_name,\n        ''email_address'', m.email_address,\n        ''imap_host'', m.imap_host,\n        ''imap_port'', m.imap_port,\n        ''provider'', m.provider,\n        ''mailbox_type'', m.mailbox_type,\n        ''is_active'', m.is_active,\n        ''is_shared_platform_mailbox'', m.is_shared_platform_mailbox,\n        ''secret_reference_present'', m.secret_reference is not null\n      ) order by m.environment, m.id)\n      from public.ediel_mailboxes m\n      where m.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', c.id,\n        ''fingerprint'', c.certificate_fingerprint,\n        ''valid_from'', c.certificate_valid_from,\n        ''valid_to'', c.certificate_valid_to,\n        ''encryption_status'', c.encryption_status,\n        ''status'', c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''active_test_configurations'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''environment'', tc.environment,\n        ''test_suite'', tc.test_suite,\n        ''actor_role'', tc.actor_role,\n        ''message_family'', tc.message_family,\n        ''setup_package'', tc.setup_package,\n        ''status'', tc.status\n      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)\n      from public.ediel_active_test_configurations tc\n      where tc.company_id = p_company_id and tc.status = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rv.id,\n        ''rule_key'', rv.rule_key,\n        ''version_code'', rv.version_code,\n        ''schema_version'', rv.schema_version,\n        ''environment'', rv.environment,\n        ''message_family'', rv.message_family,\n        ''message_code'', rv.message_code,\n        ''business_process'', rv.business_process,\n        ''source_version'', rv.source_version,\n        ''status'', rv.status,\n        ''is_active'', rv.is_active\n      ) order by rv.rule_key, rv.version_code, rv.id)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active, false) = true\n        and coalesce(rv.status, ''active'') = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_packs'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rp.id,\n        ''market'', rp.market,\n        ''family'', rp.family,\n        ''guide_version'', rp.guide_version,\n        ''guide_revision'', rp.guide_revision,\n        ''unh_association_code'', rp.unh_association_code,\n        ''valid_from'', rp.valid_from,\n        ''valid_to'', rp.valid_to,\n        ''status'', rp.status,\n        ''source_hash'', rp.source_hash,\n        ''field_matrix_version'', rp.field_matrix_version,\n        ''code_list_versions'', rp.code_list_versions\n      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)\n      from public.ediel_rule_packs rp\n      where rp.status = ''active''\n    ), ''[]''::jsonb),\n    ''enabled_message_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', mp.id,\n        ''rule_pack_id'', mp.rule_pack_id,\n        ''message_code'', mp.message_code,\n        ''transaction_subtype'', mp.transaction_subtype,\n        ''direction'', mp.direction,\n        ''business_process'', mp.business_process,\n        ''phase'', mp.phase,\n        ''profile_key'', mp.profile_key,\n        ''profile'', mp.profile,\n        ''is_enabled'', mp.is_enabled\n      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)\n      from public.ediel_message_profiles mp\n      where mp.is_enabled = true\n    ), ''[]''::jsonb),\n    ''active_tenant_rule_profile_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rpv.id,\n        ''rule_profile_id'', rpv.rule_profile_id,\n        ''profile_key'', rpv.profile_key,\n        ''version'', rpv.version,\n        ''status'', rpv.status,\n        ''checksum'', rpv.checksum,\n        ''source_revision'', rpv.source_revision,\n        ''rules'', rpv.rules\n      ) order by rpv.profile_key, rpv.version, rpv.id)\n      from public.ediel_rule_profile_versions rpv\n      where rpv.company_id = p_company_id and rpv.status = ''active''\n    ), ''[]''::jsonb),\n    ''engine_version'', ''canonical-evidence-v3''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text, ''utf8''), ''sha256''), ''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id and configuration_hash = v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version), 0) + 1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,\n    test_brp_ediel_id, production_brp_ediel_id,\n    test_application_reference, production_application_reference,\n    primary_test_route_id, primary_production_route_id, payload, configuration_hash,\n    reason, created_by\n  ) values (\n    p_company_id,\n    v_next_version,\n    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n    v_company.test_ediel_id,\n    v_company.production_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.test_application_reference,\n    v_company.production_application_reference,\n    v_company.ediel_primary_test_route_profile_id,\n    v_company.ediel_primary_production_route_profile_id,\n    v_payload,\n    v_hash,\n    coalesce(nullif(btrim(p_reason), ''''), ''configuration_changed''),\n    p_actor_user_id\n  ) returning * into v_snapshot;\n\n  -- Exactly one durable readiness revalidation job per immutable snapshot.\n  insert into public.company_provisioning_jobs(\n    company_id,\n    job_key,\n    status,\n    idempotency_key,\n    available_at,\n    last_error_details\n  ) values (\n    p_company_id,\n    ''ediel_readiness_revalidate'',\n    ''pending'',\n    v_snapshot.id::text,\n    now(),\n    ''{}''::jsonb\n  )\n  on conflict (company_id, job_key, idempotency_key) do nothing;\n\n  update public.ediel_test_runs\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      stale_at = now()\n  where company_id = p_company_id\n    and completed_at is not null\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.actor_test_results\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      updated_at = now()\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_readiness_checks\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_go_live_events\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and event_type = ''production_dry_run''\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_state\n  set configuration_snapshot_id = v_snapshot.id,\n      state = case when state in (''prepared'', ''live'') then ''blocked'' else state end,\n      blocked_reason = case when state in (''prepared'', ''live'') then ''configuration_changed'' else blocked_reason end,\n      state_version = state_version + 1,\n      updated_at = now()\n  where company_id = p_company_id;\n\n  if exists(\n    select 1 from public.ediel_production_state\n    where company_id = p_company_id and state = ''blocked''\n  ) then\n    update public.companies\n    set production_status = ''blocked'',\n        ediel_production_status = ''blocked'',\n        live_ediel_enabled = false,\n        ediel_production_enabled = false,\n        live_blocked_reason = ''configuration_changed'',\n        updated_at = now()\n    where id = p_company_id;\n\n    insert into public.ediel_send_locks(\n      company_id, environment, locked, locked_reason, locked_at, updated_at\n    ) values (\n      p_company_id, ''production'', true, ''configuration_changed'', now(), now()\n    )\n    on conflict (company_id, environment) do update\n    set locked = true,\n        locked_reason = ''configuration_changed'',\n        locked_at = now(),\n        updated_at = now();\n  end if;\n\n  return v_snapshot;\nend;\n","patched":"\ndeclare\n  v_company public.companies%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\nbegin\n  if p_company_id is null then raise exception ''company_id_required''; end if;\n  select * into v_company from public.companies where id = p_company_id for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  v_payload := jsonb_build_object(\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n      ''test_ediel_id'', v_company.test_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', v_company.brp_ediel_id,\n      ''test_application_reference'', v_company.test_application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''test_sender_sub_address'', v_company.test_sender_sub_address,\n      ''production_sender_sub_address'', v_company.production_sender_sub_address,\n      ''test_mailbox'', v_company.test_mailbox,\n      ''production_mailbox'', v_company.production_mailbox,\n      ''primary_test_route_id'', v_company.ediel_primary_test_route_profile_id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', a.id,\n        ''environment'', a.environment,\n        ''actor_role'', coalesce(a.actor_role, a.role),\n        ''ediel_id'', coalesce(a.actor_ediel_id, a.ediel_id),\n        ''sender_subaddress'', coalesce(a.sender_sub_address, a.sender_subaddress),\n        ''receiver_subaddress'', coalesce(a.receiver_sub_address, a.receiver_subaddress),\n        ''application_reference'', coalesce(a.application_reference, a.default_application_reference),\n        ''mailbox'', a.mailbox,\n        ''brp_ediel_id'', a.brp_ediel_id,\n        ''is_active'', a.is_active\n      ) order by a.environment, a.id)\n      from public.ediel_actor_settings a\n      where a.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', r.id,\n        ''environment'', r.environment,\n        ''route_type'', r.route_type,\n        ''sender_ediel_id'', r.sender_ediel_id,\n        ''sender_subaddress'', coalesce(r.sender_sub_address, r.sender_subaddress),\n        ''receiver_ediel_id'', r.receiver_ediel_id,\n        ''receiver_subaddress'', coalesce(r.receiver_sub_address, r.receiver_subaddress),\n        ''mailbox_id'', r.mailbox_id,\n        ''transport_profile_id'', r.transport_profile_id,\n        ''certificate_id'', r.certificate_id,\n        ''receiver_certificate_id'', r.receiver_certificate_id,\n        ''is_active'', r.is_active,\n        ''is_enabled'', r.is_enabled\n      ) order by r.environment, r.id)\n      from public.ediel_route_profiles r\n      where r.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', m.id,\n        ''environment'', m.environment,\n        ''mailbox_name'', m.mailbox_name,\n        ''email_address'', m.email_address,\n        ''imap_host'', m.imap_host,\n        ''imap_port'', m.imap_port,\n        ''provider'', m.provider,\n        ''mailbox_type'', m.mailbox_type,\n        ''is_active'', m.is_active,\n        ''is_shared_platform_mailbox'', m.is_shared_platform_mailbox,\n        ''secret_reference_present'', m.secret_reference is not null\n      ) order by m.environment, m.id)\n      from public.ediel_mailboxes m\n      where m.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', c.id,\n        ''fingerprint'', c.certificate_fingerprint,\n        ''valid_from'', c.certificate_valid_from,\n        ''valid_to'', c.certificate_valid_to,\n        ''encryption_status'', c.encryption_status,\n        ''status'', c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.company_id = p_company_id\n    ), ''[]''::jsonb),\n    ''active_test_configurations'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''environment'', tc.environment,\n        ''test_suite'', tc.test_suite,\n        ''actor_role'', tc.actor_role,\n        ''message_family'', tc.message_family,\n        ''setup_package'', tc.setup_package,\n        ''status'', tc.status\n      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)\n      from public.ediel_active_test_configurations tc\n      where tc.company_id = p_company_id and tc.status = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rv.id,\n        ''rule_key'', rv.rule_key,\n        ''version_code'', rv.version_code,\n        ''schema_version'', rv.schema_version,\n        ''environment'', rv.environment,\n        ''message_family'', rv.message_family,\n        ''message_code'', rv.message_code,\n        ''business_process'', rv.business_process,\n        ''source_version'', rv.source_version,\n        ''status'', rv.status,\n        ''is_active'', rv.is_active\n      ) order by rv.rule_key, rv.version_code, rv.id)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active, false) = true\n        and coalesce(rv.status, ''active'') = ''active''\n    ), ''[]''::jsonb),\n    ''active_rule_packs'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rp.id,\n        ''market'', rp.market,\n        ''family'', rp.family,\n        ''guide_version'', rp.guide_version,\n        ''guide_revision'', rp.guide_revision,\n        ''unh_association_code'', rp.unh_association_code,\n        ''valid_from'', rp.valid_from,\n        ''valid_to'', rp.valid_to,\n        ''status'', rp.status,\n        ''source_hash'', rp.source_hash,\n        ''field_matrix_version'', rp.field_matrix_version,\n        ''code_list_versions'', rp.code_list_versions\n      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)\n      from public.ediel_rule_packs rp\n      where rp.status = ''active''\n    ), ''[]''::jsonb),\n    ''enabled_message_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', mp.id,\n        ''rule_pack_id'', mp.rule_pack_id,\n        ''message_code'', mp.message_code,\n        ''transaction_subtype'', mp.transaction_subtype,\n        ''direction'', mp.direction,\n        ''business_process'', mp.business_process,\n        ''phase'', mp.phase,\n        ''profile_key'', mp.profile_key,\n        ''profile'', mp.profile,\n        ''is_enabled'', mp.is_enabled\n      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)\n      from public.ediel_message_profiles mp\n      where mp.is_enabled = true\n    ), ''[]''::jsonb),\n    ''active_tenant_rule_profile_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', rpv.id,\n        ''rule_profile_id'', rpv.rule_profile_id,\n        ''profile_key'', rpv.profile_key,\n        ''version'', rpv.version,\n        ''status'', rpv.status,\n        ''checksum'', rpv.checksum,\n        ''source_revision'', rpv.source_revision,\n        ''rules'', rpv.rules\n      ) order by rpv.profile_key, rpv.version, rpv.id)\n      from public.ediel_rule_profile_versions rpv\n      where rpv.company_id = p_company_id and rpv.status = ''active''\n    ), ''[]''::jsonb),\n    ''engine_version'', ''canonical-evidence-v3''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text, ''utf8''), ''sha256''), ''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id and configuration_hash = v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version), 0) + 1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id = p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,\n    test_brp_ediel_id, production_brp_ediel_id,\n    test_application_reference, production_application_reference,\n    primary_test_route_id, primary_production_route_id, payload, configuration_hash,\n    reason, created_by\n  ) values (\n    p_company_id,\n    v_next_version,\n    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>''market_role'', '''')),\n    v_company.test_ediel_id,\n    v_company.production_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.brp_ediel_id,\n    v_company.test_application_reference,\n    v_company.production_application_reference,\n    v_company.ediel_primary_test_route_profile_id,\n    v_company.ediel_primary_production_route_profile_id,\n    v_payload,\n    v_hash,\n    coalesce(nullif(btrim(p_reason), ''''), ''configuration_changed''),\n    p_actor_user_id\n  ) returning * into v_snapshot;\n\n  -- Exactly one durable readiness revalidation job per immutable snapshot.\n  insert into public.company_provisioning_jobs(\n    company_id,\n    job_key,\n    status,\n    idempotency_key,\n    available_at,\n    last_error_details\n  ) values (\n    p_company_id,\n    ''ediel_readiness_revalidate'',\n    ''pending'',\n    v_snapshot.id::text,\n    now(),\n    ''{}''::jsonb\n  )\n  on conflict (company_id, job_key, idempotency_key) do nothing;\n\n  update public.ediel_test_runs\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      stale_at = now()\n  where company_id = p_company_id\n    and completed_at is not null\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.actor_test_results\n  set is_stale = true,\n      stale_reason = ''configuration_changed'',\n      updated_at = now()\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_production_readiness_checks\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  update public.ediel_go_live_events\n  set is_stale = true,\n      stale_reason = ''configuration_changed''\n  where company_id = p_company_id\n    and event_type = ''production_dry_run''\n    and configuration_snapshot_id is distinct from v_snapshot.id;\n\n  -- This aggregate snapshot is retained for operations/dashboard continuity.\n  -- A dependency change invalidates only matching immutable capability proofs\n  -- on their next read; it must not pause an unrelated legal role/capability.\n  -- Explicit operator production state and send locks are preserved.\n  update public.ediel_production_state\n  set configuration_snapshot_id = v_snapshot.id,\n      updated_at = now()\n  where company_id = p_company_id;\n\n  return v_snapshot;\nend;\n","source_line":37187,"source_statement_sha256":"c7b77d20dc3f4aa613f03a4a1a32a73e7ef242925e23eba1fe0faa49c45fd7b7","expected":{"owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=public, extensions, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_company_id","p_actor_user_id","p_reason"],"proargmodes":null,"return_type":"ediel_configuration_snapshots","proretset":false,"identity_arguments":"p_company_id uuid, p_actor_user_id uuid, p_reason text","arguments":"p_company_id uuid, p_actor_user_id uuid, p_reason text","language":"plpgsql"}},{"signature":"public.canonical_capture_ediel_test_configuration_snapshot(uuid,uuid,uuid,uuid,text)","before":"cd351237978161ee32086f9b7832a0eb","after":"f8a8c3fa9b29b761dc47ebb0e465d3be","canonical_complete":"f8a8c3fa9b29b761dc47ebb0e465d3be","original":"\ndeclare\n  v_company public.companies%rowtype;\n  v_actor public.ediel_actor_settings%rowtype;\n  v_route public.ediel_route_profiles%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\n  v_actor_role text;\n  v_actor_ediel_id text;\n  v_route_sender text;\n  v_route_receiver text;\nbegin\n  if p_company_id is null or p_actor_profile_id is null or p_route_profile_id is null then\n    raise exception ''company_actor_profile_and_route_required'';\n  end if;\n  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, ''ediel.profile.write'', false) then\n    raise exception ''actor_not_authorized_for_test_configuration_snapshot'';\n  end if;\n\n  select * into v_company\n  from public.companies\n  where id=p_company_id\n  for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  select * into v_actor\n  from public.ediel_actor_settings\n  where id=p_actor_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_actor_profile_not_found''; end if;\n  if lower(coalesce(v_actor.environment,'''')) <> ''test'' or coalesce(v_actor.is_active,false) <> true then\n    raise exception ''test_actor_profile_must_be_active_test_profile'';\n  end if;\n\n  v_actor_role := case lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n    when ''supplier'' then ''supplier''\n    when ''electricity_supplier'' then ''supplier''\n    when ''esco'' then ''energy_service_company''\n    when ''energy_service_company'' then ''energy_service_company''\n    else lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n  end;\n  v_actor_ediel_id := nullif(btrim(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id)), '''');\n  if v_actor_role is null or v_actor_ediel_id is null then\n    raise exception ''test_actor_profile_identity_incomplete'';\n  end if;\n\n  select * into v_route\n  from public.ediel_route_profiles\n  where id=p_route_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_route_profile_not_found''; end if;\n  if lower(coalesce(v_route.environment,'''')) <> ''test''\n     or coalesce(v_route.is_active,true) <> true\n     or coalesce(v_route.is_enabled,true) <> true then\n    raise exception ''test_route_profile_must_be_active_test_route'';\n  end if;\n\n  v_route_sender := nullif(btrim(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id)), '''');\n  v_route_receiver := nullif(btrim(coalesce(v_route.receiver_ediel_id,v_route.counterparty_ediel_id)), '''');\n  if v_route_sender is null or upper(v_route_sender) <> upper(v_actor_ediel_id) then\n    raise exception ''test_route_sender_must_match_actor_profile'';\n  end if;\n  if v_route_receiver is null then\n    raise exception ''test_route_receiver_required'';\n  end if;\n  if v_route.actor_setting_id is not null and v_route.actor_setting_id <> v_actor.id then\n    raise exception ''test_route_actor_binding_mismatch'';\n  end if;\n\n  v_payload := jsonb_build_object(\n    ''test_context'', jsonb_build_object(\n      ''actor_profile_id'', v_actor.id,\n      ''route_profile_id'', v_route.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''counterparty_ediel_id'', v_route_receiver,\n      ''message_family'', upper(coalesce(v_route.message_family,'''')),\n      ''application_reference'', v_route.application_reference,\n      ''environment_type'', v_route.environment_type\n    ),\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),\n      ''test_application_reference'', v_route.application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''primary_test_route_id'', v_route.id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',a.id,''environment'',a.environment,''actor_role'',coalesce(a.actor_role,a.role),\n        ''ediel_id'',coalesce(a.actor_ediel_id,a.ediel_id),\n        ''sender_subaddress'',coalesce(a.sender_sub_address,a.sender_subaddress),\n        ''receiver_subaddress'',coalesce(a.receiver_sub_address,a.receiver_subaddress),\n        ''application_reference'',coalesce(a.application_reference,a.default_application_reference),\n        ''mailbox'',a.mailbox,''brp_ediel_id'',a.brp_ediel_id,''is_active'',a.is_active\n      ) order by a.environment,a.id)\n      from public.ediel_actor_settings a\n      where a.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',r.id,''environment'',r.environment,''route_type'',r.route_type,\n        ''actor_setting_id'',r.actor_setting_id,\n        ''sender_ediel_id'',r.sender_ediel_id,\n        ''sender_subaddress'',coalesce(r.sender_sub_address,r.sender_subaddress),\n        ''receiver_ediel_id'',r.receiver_ediel_id,\n        ''receiver_subaddress'',coalesce(r.receiver_sub_address,r.receiver_subaddress),\n        ''application_reference'',r.application_reference,\n        ''message_family'',r.message_family,\n        ''environment_type'',r.environment_type,\n        ''mailbox_id'',r.mailbox_id,''transport_profile_id'',r.transport_profile_id,\n        ''certificate_id'',r.certificate_id,''receiver_certificate_id'',r.receiver_certificate_id,\n        ''transport_security_mode'',r.transport_security_mode,\n        ''is_active'',r.is_active,''is_enabled'',r.is_enabled\n      ) order by r.environment,r.id)\n      from public.ediel_route_profiles r\n      where r.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',m.id,''environment'',m.environment,''mailbox_name'',m.mailbox_name,\n        ''email_address'',m.email_address,''provider'',m.provider,''mailbox_type'',m.mailbox_type,\n        ''transport_mode'',m.transport_mode,''tls_required'',m.tls_required,\n        ''signing_mode'',m.signing_mode,''encryption_mode'',m.encryption_mode,\n        ''is_active'',m.is_active,''is_shared_platform_mailbox'',m.is_shared_platform_mailbox\n      ) order by m.environment,m.id)\n      from public.ediel_mailboxes m\n      where m.company_id=p_company_id or m.id=v_route.mailbox_id\n    ),''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',c.id,''fingerprint'',coalesce(c.fingerprint_sha256,c.certificate_fingerprint),\n        ''owner_ediel_id'',c.owner_ediel_id,''owner_subaddress'',c.owner_subaddress,\n        ''message_family'',c.message_family,''purpose'',c.purpose,''usage'',c.usage,\n        ''valid_from'',coalesce(c.valid_from,c.certificate_valid_from),\n        ''valid_to'',coalesce(c.valid_to,c.certificate_valid_to),\n        ''encryption_status'',c.encryption_status,''status'',c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.id in (v_route.certificate_id,v_route.receiver_certificate_id)\n    ),''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''rule_key'',rv.rule_key,''version_code'',rv.version_code,''schema_version'',rv.schema_version,\n        ''environment'',rv.environment,''status'',rv.status,''is_active'',rv.is_active\n      ) order by rv.rule_key,rv.version_code)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active,false)=true and coalesce(rv.status,''active'')=''active''\n    ),''[]''::jsonb),\n    ''engine_version'',''canonical-evidence-v3-role-scoped''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text,''utf8''),''sha256''),''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id and configuration_hash=v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version),0)+1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id,snapshot_version,actor_role,test_ediel_id,production_ediel_id,\n    test_brp_ediel_id,production_brp_ediel_id,\n    test_application_reference,production_application_reference,\n    primary_test_route_id,primary_production_route_id,payload,configuration_hash,\n    reason,created_by\n  ) values (\n    p_company_id,v_next_version,v_actor_role,v_actor_ediel_id,v_company.production_ediel_id,\n    coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),v_company.brp_ediel_id,\n    v_route.application_reference,v_company.production_application_reference,\n    v_route.id,v_company.ediel_primary_production_route_profile_id,\n    v_payload,v_hash,coalesce(nullif(btrim(p_reason),''''),''test_configuration_changed''),p_actor_user_id\n  ) returning * into v_snapshot;\n\n  update public.ediel_test_runs r\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',stale_at=now()\n  where r.company_id=p_company_id\n    and r.completed_at is not null\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  update public.actor_test_results ar\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',updated_at=now()\n  from public.ediel_test_runs r\n  where ar.company_id=p_company_id\n    and ar.ediel_test_run_id=r.id\n    and r.company_id=p_company_id\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  return v_snapshot;\nend;\n","patched":"\ndeclare\n  v_company public.companies%rowtype;\n  v_actor public.ediel_actor_settings%rowtype;\n  v_route public.ediel_route_profiles%rowtype;\n  v_communication_route public.communication_routes%rowtype;\n  v_payload jsonb;\n  v_hash text;\n  v_next_version bigint;\n  v_snapshot public.ediel_configuration_snapshots%rowtype;\n  v_existing public.ediel_configuration_snapshots%rowtype;\n  v_actor_role text;\n  v_actor_ediel_id text;\n  v_route_sender text;\n  v_route_receiver text;\nbegin\n  if p_company_id is null or p_actor_profile_id is null or p_route_profile_id is null then\n    raise exception ''company_actor_profile_and_route_required'';\n  end if;\n  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, ''ediel.profile.write'', false) then\n    raise exception ''actor_not_authorized_for_test_configuration_snapshot'';\n  end if;\n\n  select * into v_company\n  from public.companies\n  where id=p_company_id\n  for update;\n  if not found then raise exception ''tenant_not_found''; end if;\n\n  select * into v_actor\n  from public.ediel_actor_settings\n  where id=p_actor_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_actor_profile_not_found''; end if;\n  if lower(coalesce(v_actor.environment,'''')) <> ''test'' or coalesce(v_actor.is_active,false) <> true then\n    raise exception ''test_actor_profile_must_be_active_test_profile'';\n  end if;\n\n  v_actor_role := case lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n    when ''supplier'' then ''supplier''\n    when ''electricity_supplier'' then ''supplier''\n    when ''esco'' then ''energy_service_company''\n    when ''energy_service_company'' then ''energy_service_company''\n    else lower(coalesce(nullif(v_actor.actor_role,''''),v_actor.role))\n  end;\n  v_actor_ediel_id := nullif(btrim(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id)), '''');\n  if v_actor_role is null or v_actor_ediel_id is null then\n    raise exception ''test_actor_profile_identity_incomplete'';\n  end if;\n\n  select * into v_route\n  from public.ediel_route_profiles\n  where id=p_route_profile_id and company_id=p_company_id\n  for share;\n  if not found then raise exception ''tenant_scoped_test_route_profile_not_found''; end if;\n  if lower(coalesce(v_route.environment,'''')) <> ''test''\n     or coalesce(v_route.is_active,true) <> true\n     or coalesce(v_route.is_enabled,true) <> true then\n    raise exception ''test_route_profile_must_be_active_test_route'';\n  end if;\n\n  v_route_sender := nullif(btrim(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id)), '''');\n  v_route_receiver := nullif(btrim(coalesce(v_route.receiver_ediel_id,v_route.counterparty_ediel_id)), '''');\n  if v_route_sender is null or upper(v_route_sender) <> upper(v_actor_ediel_id) then\n    raise exception ''test_route_sender_must_match_actor_profile'';\n  end if;\n  if v_route_receiver is null then\n    raise exception ''test_route_receiver_required'';\n  end if;\n  if v_route.actor_setting_id is not null and v_route.actor_setting_id <> v_actor.id then\n    raise exception ''test_route_actor_binding_mismatch'';\n  end if;\n\n  select * into v_communication_route\n  from public.communication_routes\n  where id=v_route.communication_route_id and company_id=p_company_id\n  for share;\n  if not found or v_communication_route.is_active is distinct from true\n     or v_communication_route.environment_type is null\n     or v_communication_route.environment_type not in (''agt_test'',''tgt_test'',''bilateral_test'') then\n    raise exception ''test_route_communication_source_required'';\n  end if;\n\n  v_payload := jsonb_build_object(\n    ''test_context'', jsonb_build_object(\n      ''actor_profile_id'', v_actor.id,\n      ''route_profile_id'', v_route.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''counterparty_ediel_id'', v_route_receiver,\n      ''message_family'', upper(coalesce(v_route.message_family,'''')),\n      ''application_reference'', v_route.application_reference,\n      ''environment_type'', v_communication_route.environment_type\n    ),\n    ''company'', jsonb_build_object(\n      ''id'', v_company.id,\n      ''actor_role'', v_actor_role,\n      ''test_ediel_id'', v_actor_ediel_id,\n      ''production_ediel_id'', v_company.production_ediel_id,\n      ''brp_ediel_id'', coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),\n      ''test_application_reference'', v_route.application_reference,\n      ''production_application_reference'', v_company.production_application_reference,\n      ''primary_test_route_id'', v_route.id,\n      ''primary_production_route_id'', v_company.ediel_primary_production_route_profile_id\n    ),\n    ''actor_profiles'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',a.id,''environment'',a.environment,''actor_role'',coalesce(a.actor_role,a.role),\n        ''ediel_id'',coalesce(a.actor_ediel_id,a.ediel_id),\n        ''sender_subaddress'',coalesce(a.sender_sub_address,a.sender_subaddress),\n        ''receiver_subaddress'',coalesce(a.receiver_sub_address,a.receiver_subaddress),\n        ''application_reference'',coalesce(a.application_reference,a.default_application_reference),\n        ''mailbox'',a.mailbox,''brp_ediel_id'',a.brp_ediel_id,''is_active'',a.is_active\n      ) order by a.environment,a.id)\n      from public.ediel_actor_settings a\n      where a.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''routes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',r.id,''environment'',r.environment,''route_type'',r.route_type,\n        ''actor_setting_id'',r.actor_setting_id,\n        ''sender_ediel_id'',r.sender_ediel_id,\n        ''sender_subaddress'',coalesce(r.sender_sub_address,r.sender_subaddress),\n        ''receiver_ediel_id'',r.receiver_ediel_id,\n        ''receiver_subaddress'',coalesce(r.receiver_sub_address,r.receiver_subaddress),\n        ''application_reference'',r.application_reference,\n        ''message_family'',r.message_family,\n        ''environment_type'',cr.environment_type,\n        ''mailbox_id'',r.mailbox_id,''transport_profile_id'',r.transport_profile_id,\n        ''certificate_id'',r.certificate_id,''receiver_certificate_id'',r.receiver_certificate_id,\n        ''transport_security_mode'',r.transport_security_mode,\n        ''is_active'',r.is_active,''is_enabled'',r.is_enabled\n      ) order by r.environment,r.id)\n      from public.ediel_route_profiles r\n      left join public.communication_routes cr\n        on cr.id=r.communication_route_id and cr.company_id=r.company_id\n      where r.company_id=p_company_id\n    ),''[]''::jsonb),\n    ''mailboxes'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',m.id,''environment'',m.environment,''mailbox_name'',m.mailbox_name,\n        ''email_address'',m.email_address,''provider'',m.provider,''mailbox_type'',m.mailbox_type,\n        ''transport_mode'',m.transport_mode,''tls_required'',m.tls_required,\n        ''signing_mode'',m.signing_mode,''encryption_mode'',m.encryption_mode,\n        ''is_active'',m.is_active,''is_shared_platform_mailbox'',m.is_shared_platform_mailbox\n      ) order by m.environment,m.id)\n      from public.ediel_mailboxes m\n      where m.company_id=p_company_id or m.id=v_route.mailbox_id\n    ),''[]''::jsonb),\n    ''certificates'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'',c.id,''fingerprint'',coalesce(c.fingerprint_sha256,c.certificate_fingerprint),\n        ''owner_ediel_id'',c.owner_ediel_id,''owner_subaddress'',c.owner_subaddress,\n        ''message_family'',c.message_family,''purpose'',c.purpose,''usage'',c.usage,\n        ''valid_from'',coalesce(c.valid_from,c.certificate_valid_from),\n        ''valid_to'',coalesce(c.valid_to,c.certificate_valid_to),\n        ''encryption_status'',c.encryption_status,''status'',c.status\n      ) order by c.id)\n      from public.ediel_certificates c\n      where c.id in (v_route.certificate_id,v_route.receiver_certificate_id)\n    ),''[]''::jsonb),\n    ''active_rule_versions'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''rule_key'',rv.rule_key,''version_code'',rv.version_code,''schema_version'',rv.schema_version,\n        ''environment'',rv.environment,''status'',rv.status,''is_active'',rv.is_active\n      ) order by rv.rule_key,rv.version_code)\n      from public.ediel_rule_versions rv\n      where coalesce(rv.is_active,false)=true and coalesce(rv.status,''active'')=''active''\n    ),''[]''::jsonb),\n    ''engine_version'',''canonical-evidence-v3-role-scoped''\n  );\n\n  v_hash := encode(digest(convert_to(v_payload::text,''utf8''),''sha256''),''hex'');\n  select * into v_existing\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id and configuration_hash=v_hash;\n  if found then return v_existing; end if;\n\n  select coalesce(max(snapshot_version),0)+1 into v_next_version\n  from public.ediel_configuration_snapshots\n  where company_id=p_company_id;\n\n  insert into public.ediel_configuration_snapshots(\n    company_id,snapshot_version,actor_role,test_ediel_id,production_ediel_id,\n    test_brp_ediel_id,production_brp_ediel_id,\n    test_application_reference,production_application_reference,\n    primary_test_route_id,primary_production_route_id,payload,configuration_hash,\n    reason,created_by\n  ) values (\n    p_company_id,v_next_version,v_actor_role,v_actor_ediel_id,v_company.production_ediel_id,\n    coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),v_company.brp_ediel_id,\n    v_route.application_reference,v_company.production_application_reference,\n    v_route.id,v_company.ediel_primary_production_route_profile_id,\n    v_payload,v_hash,coalesce(nullif(btrim(p_reason),''''),''test_configuration_changed''),p_actor_user_id\n  ) returning * into v_snapshot;\n\n  update public.ediel_test_runs r\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',stale_at=now()\n  where r.company_id=p_company_id\n    and r.completed_at is not null\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  update public.actor_test_results ar\n  set is_stale=true,stale_reason=''role_scoped_test_configuration_changed'',updated_at=now()\n  from public.ediel_test_runs r\n  where ar.company_id=p_company_id\n    and ar.ediel_test_run_id=r.id\n    and r.company_id=p_company_id\n    and r.configuration_snapshot_id is distinct from v_snapshot.id\n    and case lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n      when ''supplier'' then ''supplier''\n      when ''electricity_supplier'' then ''supplier''\n      when ''esco'' then ''energy_service_company''\n      when ''energy_service_company'' then ''energy_service_company''\n      else lower(coalesce(nullif(r.actor_role,''''),r.role_code))\n    end = v_actor_role\n    and upper(coalesce(r.message_family,r.test_suite,'''')) = upper(coalesce(v_route.message_family,r.test_suite,''''));\n\n  return v_snapshot;\nend;\n","source_line":37461,"source_statement_sha256":"4b151da5eaa7b7bf9cc8f37ab6a31112952188891d6d2127558744ac9c88bfdb","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public, extensions, pg_temp"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_company_id","p_actor_user_id","p_actor_profile_id","p_route_profile_id","p_reason"],"proargmodes":null,"return_type":"ediel_configuration_snapshots","proretset":false,"identity_arguments":"p_company_id uuid, p_actor_user_id uuid, p_actor_profile_id uuid, p_route_profile_id uuid, p_reason text","arguments":"p_company_id uuid, p_actor_user_id uuid, p_actor_profile_id uuid, p_route_profile_id uuid, p_reason text","language":"plpgsql"}},{"signature":"public.claim_ediel_outbox_item(uuid,text,uuid)","before":"9652162f0f7e0971221ac74439ffc875","after":"8b9e258bbc9f662aeb572ed4432bf0fe","canonical_complete":"8b9e258bbc9f662aeb572ed4432bf0fe","original":"\nbegin\n  if p_outbox_item_id is null or nullif(trim(p_worker_id),'''') is null or p_actor_user_id is null then\n    raise exception ''ediel_outbox_claim_arguments_required'' using errcode=''22023'';\n  end if;\n  return query\n  with claimed as (\n    update public.ediel_outbox o\n       set status=''sending'',locked_at=now(),locked_by=p_worker_id,\n           attempts=coalesce(o.attempts,0)+1,\n           send_attempt_count=coalesce(o.send_attempt_count,0)+1,\n           current_send_attempt_id=gen_random_uuid(),updated_by=p_actor_user_id,updated_at=now()\n     where o.id=p_outbox_item_id\n       and o.company_id is not null\n       and o.status in (''prepared'',''queued'')\n       and exists(\n         select 1 from public.ediel_messages m\n         where m.id=o.ediel_message_id and m.company_id=o.company_id and m.direction=''outbound''\n           and m.rule_profile_version_id is not null and nullif(m.rule_pack_checksum,'''') is not null\n       )\n     returning o.*\n  ) select * from claimed;\nend; ","patched":"\nDECLARE candidate public.ediel_outbox%rowtype;locked_outbox public.ediel_outbox%rowtype;\n ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;\n basis jsonb;initial_basis jsonb;e jsonb;technical boolean:=false;pass integer;\nbegin\n  if p_outbox_item_id is null or nullif(trim(p_worker_id),'''') is null or p_actor_user_id is null then\n    raise exception ''ediel_outbox_claim_arguments_required'' using errcode=''22023'';\n  end if;\n  -- Routing peek only. Never take an outbox/message row lock before the\n  -- unchanged private reader acquires its current graph and source receipts.\n  SELECT * INTO candidate FROM public.ediel_outbox WHERE id=p_outbox_item_id;\n  IF candidate.company_id IS NOT NULL AND candidate.status IN (''prepared'',''queued'') THEN\n    SELECT * INTO ack FROM public.ediel_messages WHERE id=candidate.ediel_message_id;\n    IF ack.company_id=candidate.company_id AND ack.environment=candidate.environment\n       AND ack.environment IN (''test'',''production'') AND ack.direction=''outbound''\n       AND ack.message_family=''CONTRL'' AND ack.canonical_rule_pack_id IS NULL\n       AND ack.rule_profile_version_id IS NULL AND ack.rule_pack_checksum IS NULL THEN\n      initial_basis:=gridex_ediel_technical_ack.read_persisted_contrl_v2(\n        candidate.company_id,candidate.environment,candidate.ediel_message_id,p_actor_user_id,''send'');\n      FOR pass IN 1..2 LOOP\n        basis:=initial_basis;\n        IF pass=2 THEN\n          -- The first call already holds this same complete graph/source chain.\n          -- Revalidate current actor/phase/endpoint after the outbox lock wait.\n          basis:=gridex_ediel_technical_ack.read_persisted_contrl_v2(\n            candidate.company_id,candidate.environment,candidate.ediel_message_id,p_actor_user_id,''send'');\n          IF basis IS DISTINCT FROM initial_basis THEN\n            RAISE EXCEPTION ''ediel_technical_contrl_claim_basis_changed'' USING ERRCODE=''23514'';\n          END IF;\n        END IF;\n        e:=basis->''technicalSyntaxAckEvidence'';\n        IF jsonb_typeof(basis) IS DISTINCT FROM ''object'' OR basis->''version'' IS DISTINCT FROM ''2''::jsonb\n           OR basis->>''executionActorUserId'' IS DISTINCT FROM p_actor_user_id::text\n           OR basis->>''executionPhase'' IS DISTINCT FROM ''send''\n           OR jsonb_typeof(basis->''ackMessage'') IS DISTINCT FROM ''object''\n           OR jsonb_typeof(e) IS DISTINCT FROM ''object'' OR e->''version'' IS DISTINCT FROM ''1''::jsonb\n           OR e->>''kind'' IS DISTINCT FROM ''technical_syntax_ack''\n           OR e->>''companyId'' IS DISTINCT FROM candidate.company_id::text\n           OR e->>''environment'' IS DISTINCT FROM candidate.environment\n           OR (e->>''syntaxDecision'' IN (''accepted'',''rejected'')) IS NOT TRUE\n           OR (e->>''sourceMessageId'' ~ ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'') IS NOT TRUE\n           OR (e->>''sourceHash'' ~ ''^[0-9a-f]{64}$'') IS NOT TRUE THEN\n          RAISE EXCEPTION ''ediel_technical_contrl_claim_basis_required'' USING ERRCODE=''23514'';\n        END IF;\n        SELECT * INTO ack FROM public.ediel_messages WHERE id=candidate.ediel_message_id FOR SHARE;\n        SELECT * INTO source FROM public.ediel_messages WHERE id=(e->>''sourceMessageId'')::uuid FOR SHARE;\n        IF ack.id IS NULL OR ack.company_id IS DISTINCT FROM candidate.company_id\n           OR ack.environment IS DISTINCT FROM candidate.environment OR ack.direction IS DISTINCT FROM ''outbound''\n           OR ack.message_family IS DISTINCT FROM ''CONTRL'' OR ack.canonical_rule_pack_id IS NOT NULL\n           OR ack.rule_profile_version_id IS NOT NULL OR ack.rule_pack_checksum IS NOT NULL\n           OR nullif(ack.raw_payload,'''') IS NULL OR ack.immutable_rendered_at IS NULL\n           OR ack.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,''UTF8'')),''hex'')\n           OR (to_jsonb(ack)-ARRAY[''related_message_id'',''ack_outcome'']) IS DISTINCT FROM\n              ((basis->''ackMessage'')-ARRAY[''related_message_id'',''ack_outcome''])\n           OR basis#>>''{ackMessage,related_message_id}'' IS DISTINCT FROM e->>''sourceMessageId''\n           OR basis#>>''{ackMessage,ack_outcome}'' IS DISTINCT FROM\n              (CASE e->>''syntaxDecision'' WHEN ''accepted'' THEN ''positive'' WHEN ''rejected'' THEN ''negative'' END)\n           OR source.id IS NULL OR source.direction IS DISTINCT FROM ''inbound''\n           OR source.environment IS DISTINCT FROM candidate.environment\n           OR (source.company_id IS NOT NULL AND source.company_id IS DISTINCT FROM candidate.company_id)\n           OR nullif(source.raw_payload,'''') IS NULL\n           -- Inbound original hash and outbound reply hash are different seals.\n           OR e->>''sourceHash'' IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,''UTF8'')),''hex'') THEN\n          RAISE EXCEPTION ''ediel_technical_contrl_claim_current_binding_required'' USING ERRCODE=''23514'';\n        END IF;\n        IF pass=1 THEN\n          SELECT * INTO locked_outbox FROM public.ediel_outbox WHERE id=p_outbox_item_id FOR UPDATE;\n          IF locked_outbox.id IS NULL OR locked_outbox.company_id IS DISTINCT FROM ack.company_id\n             OR locked_outbox.environment IS DISTINCT FROM ack.environment\n             OR locked_outbox.ediel_message_id IS DISTINCT FROM ack.id\n             OR (locked_outbox.status IN (''prepared'',''queued'')) IS NOT TRUE\n             OR to_jsonb(locked_outbox) IS DISTINCT FROM to_jsonb(candidate) THEN\n            RETURN;\n          END IF;\n        END IF;\n      END LOOP;\n      -- Re-read after the last private call; no stale routing snapshot is an\n      -- authority Boolean. Competing transactions cannot change this locked row.\n      SELECT * INTO locked_outbox FROM public.ediel_outbox WHERE id=p_outbox_item_id FOR UPDATE;\n      IF to_jsonb(locked_outbox) IS DISTINCT FROM to_jsonb(candidate) THEN RETURN;END IF;\n      technical:=true;\n    END IF;\n  END IF;\n  return query\n  with claimed as (\n    update public.ediel_outbox o\n       set status=''sending'',locked_at=now(),locked_by=p_worker_id,\n           attempts=coalesce(o.attempts,0)+1,\n           send_attempt_count=coalesce(o.send_attempt_count,0)+1,\n           current_send_attempt_id=gen_random_uuid(),updated_by=p_actor_user_id,updated_at=now()\n     where o.id=p_outbox_item_id\n       and o.company_id is not null\n       and o.status in (''prepared'',''queued'')\n       and exists(\n         select 1 from public.ediel_messages m\n         where m.id=o.ediel_message_id and m.company_id=o.company_id and m.direction=''outbound''\n           and ((m.rule_profile_version_id is not null and nullif(m.rule_pack_checksum,'''') is not null)\n             or (technical and m.id=ack.id and to_jsonb(m)=to_jsonb(ack)))\n       )\n     returning o.*\n  ) select * from claimed;\nend; ","source_line":43004,"source_statement_sha256":"cdfc047c3712cb0a3fd5d41fdc3a81d766aeae2680f70caa0ab9f0a92651a4e3","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":1000,"proargnames":["p_outbox_item_id","p_worker_id","p_actor_user_id"],"proargmodes":null,"return_type":"ediel_outbox","proretset":true,"identity_arguments":"p_outbox_item_id uuid, p_worker_id text, p_actor_user_id uuid","arguments":"p_outbox_item_id uuid, p_worker_id text, p_actor_user_id uuid","language":"plpgsql"}},{"signature":"gridex_received_sources.append_validation(uuid,text,uuid,text,text)","before":"de6d0a69327e00e3c144c71233ad41bf","after":"7326766d1107da1d261c84796bf1e059","canonical_complete":"7326766d1107da1d261c84796bf1e059","original":"\nDECLARE src gridex_received_sources.sources%rowtype; facts jsonb; pack jsonb; v_previous uuid; v_id uuid; v_hash text; facet jsonb; obj jsonb; reg jsonb; key text; object_keys text[]:=ARRAY[]::text[]; line_ids text[]:=ARRAY[]::text[]; segment_ids int[]:=ARRAY[]::int[]; previous_segment int; position int;\nBEGIN\n  -- Lock per source before selecting a predecessor. Concurrent assessments\n  -- append a single linked sequence; no UPDATE of historic decisions occurs.\n  SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id\n    AND company_id=p_company_id AND environment=p_environment FOR UPDATE;\n  IF NOT FOUND OR src.payload_hash IS NULL OR src.received_context IS NULL\n    OR p_source_payload_hash IS DISTINCT FROM src.payload_hash OR p_facts_text IS NULL OR octet_length(p_facts_text)>65536 THEN\n    RAISE EXCEPTION ''received_validation_source_unavailable'' USING ERRCODE=''23514'';\n  END IF;\n  facts:=p_facts_text::jsonb;\n  IF jsonb_typeof(facts) IS DISTINCT FROM ''object''\n    OR facts - ARRAY[''version'',''owner'',''sourceDisposition'',''objectDisposition'',''partyDisposition'',''coverage'',''originalTenantMatch'',''syntaxDecision'',''applicationDecision'',''functionalDecision'',''messageReference'',''reasonCodes'',''rulePackEvidence'',''registerValidation''] <> ''{}''::jsonb\n    OR facts->''version'' IS DISTINCT FROM ''1''::jsonb OR facts->>''owner'' IS DISTINCT FROM ''canonical-runtime-with-registry-v1''\n    OR facts->>''sourceDisposition'' IS DISTINCT FROM ''not_established'' OR facts->>''objectDisposition'' IS DISTINCT FROM ''not_checked''\n    OR facts->>''partyDisposition'' IS DISTINCT FROM ''not_checked'' OR facts->>''coverage'' IS DISTINCT FROM ''canonical_runtime_only''\n    OR facts->>''originalTenantMatch'' IS DISTINCT FROM ''matched''\n    OR coalesce(facts->>''syntaxDecision'','''') NOT IN (''accepted'',''rejected'',''not_applicable'',''manual_review'')\n    OR coalesce(facts->>''applicationDecision'','''') NOT IN (''accepted'',''rejected'',''not_applicable'',''manual_review'')\n    OR coalesce(facts->>''functionalDecision'','''') NOT IN (''accepted'',''rejected'',''not_applicable'',''manual_review'')\n    OR jsonb_typeof(facts->''reasonCodes'') IS DISTINCT FROM ''array'' OR jsonb_array_length(facts->''reasonCodes'')>128\n    OR coalesce(jsonb_typeof(facts->''messageReference''),''missing'') NOT IN (''string'',''null'')\n    OR length(coalesce(facts->>''messageReference'',''''))>128 THEN\n    RAISE EXCEPTION ''received_validation_not_source_approval'' USING ERRCODE=''23514'';\n  END IF;\n  IF EXISTS (SELECT FROM jsonb_array_elements(facts->''reasonCodes'') AS value WHERE jsonb_typeof(value) IS DISTINCT FROM ''string'' OR value#>>''{}'' !~ ''^[A-Za-z0-9_.:-]{1,128}$'') THEN\n    RAISE EXCEPTION ''received_validation_reason_unavailable'' USING ERRCODE=''23514'';\n  END IF;\n  pack:=facts->''rulePackEvidence'';\n  IF facts->>''applicationDecision''=''accepted'' AND (pack IS NULL OR pack=''null''::jsonb) THEN\n    RAISE EXCEPTION ''received_validation_rule_evidence_unavailable'' USING ERRCODE=''23514'';\n  END IF;\n  IF pack IS DISTINCT FROM ''null''::jsonb THEN\n    IF jsonb_typeof(pack) IS DISTINCT FROM ''object'' OR pack - ARRAY[''profileKey'',''messageProfileId'',''rulePackId'',''sourceHash''] <> ''{}''::jsonb\n      OR NOT EXISTS(SELECT FROM public.ediel_message_profiles profile JOIN public.ediel_rule_packs rulepack ON rulepack.id=profile.rule_pack_id\n        WHERE profile.id::text=pack->>''messageProfileId'' AND profile.profile_key=pack->>''profileKey''\n          AND rulepack.id::text=pack->>''rulePackId'' AND rulepack.source_hash=pack->>''sourceHash'') THEN\n      RAISE EXCEPTION ''received_validation_rule_evidence_unavailable'' USING ERRCODE=''23514'';\n    END IF;\n  END IF;\n  -- Optional live-owner register facet. Historical facet-only callers remain\n  -- valid. This never grants full source, tenant, legal-party or business approval.\n  IF facts ? ''registerValidation'' THEN\n    facet:=facts->''registerValidation'';\n    IF pack IS NULL OR pack=''null''::jsonb OR jsonb_typeof(facet) IS DISTINCT FROM ''object''\n      OR NOT facet ?& ARRAY[''version'',''owner'',''coverage'',''objects'']\n      OR facet-ARRAY[''version'',''owner'',''coverage'',''objects''] <> ''{}''::jsonb\n      OR facet->''version'' IS DISTINCT FROM ''1''::jsonb\n      OR facet->>''owner'' IS DISTINCT FROM ''validateProdatRegisterPolicy''\n      OR facet->>''coverage'' IS DISTINCT FROM ''canonical_register_only''\n      OR jsonb_typeof(facet->''objects'') IS DISTINCT FROM ''array'' THEN\n      RAISE EXCEPTION ''received_register_facet_invalid'' USING ERRCODE=''23514'';\n    END IF;\n    IF jsonb_array_length(facet->''objects'')>8192 THEN\n      RAISE EXCEPTION ''received_register_facet_budget'' USING ERRCODE=''23514'';\n    END IF;\n    FOR obj IN SELECT value FROM jsonb_array_elements(facet->''objects'') LOOP\n      IF jsonb_typeof(obj) IS DISTINCT FROM ''object''\n        OR NOT obj ?& ARRAY[''messageIndex'',''messageReference'',''objectId'',''identityAgency'',''disposition'',''registers'',''reasons'']\n        OR obj-ARRAY[''messageIndex'',''messageReference'',''objectId'',''identityAgency'',''disposition'',''registers'',''reasons''] <> ''{}''::jsonb\n        OR jsonb_typeof(obj->''messageIndex'') IS DISTINCT FROM ''number''\n        OR coalesce(obj->>''messageIndex'','''') !~ ''^(-1|[0-9]{1,4})$''\n        OR coalesce(obj->>''disposition'','''') NOT IN (''accepted'',''rejected'',''unavailable'')\n        OR jsonb_typeof(obj->''registers'') IS DISTINCT FROM ''array''\n        OR jsonb_typeof(obj->''reasons'') IS DISTINCT FROM ''array'' THEN\n        RAISE EXCEPTION ''received_register_object_invalid'' USING ERRCODE=''23514'';\n      END IF;\n      IF (obj->>''messageIndex'')::int>=8192 OR jsonb_array_length(obj->''registers'') NOT BETWEEN 1 AND 8192\n        OR jsonb_array_length(obj->''reasons'')>128 THEN\n        RAISE EXCEPTION ''received_register_object_budget'' USING ERRCODE=''23514'';\n      END IF;\n      FOREACH key IN ARRAY ARRAY[''messageReference'',''objectId'',''identityAgency''] LOOP\n        IF obj->key IS DISTINCT FROM ''null''::jsonb AND (jsonb_typeof(obj->key) IS DISTINCT FROM ''string''\n          OR length(obj->>key) NOT BETWEEN 1 AND 128 OR obj->>key <> btrim(obj->>key) OR obj->>key ~ ''[[:cntrl:]]'') THEN\n          RAISE EXCEPTION ''received_register_identity_invalid'' USING ERRCODE=''23514'';\n        END IF;\n      END LOOP;\n      IF obj->>''disposition''<>''unavailable'' AND ((obj->>''messageIndex'')::int<>0 OR jsonb_typeof(obj->''messageReference'')<>''string''\n        OR jsonb_typeof(obj->''objectId'')<>''string'' OR coalesce(obj->>''identityAgency'','''') NOT IN (''9'',''89'')) THEN\n        RAISE EXCEPTION ''received_register_unvalidated_scope'' USING ERRCODE=''23514'';\n      END IF;\n      IF (obj->>''disposition''=''accepted'') IS DISTINCT FROM (jsonb_array_length(obj->''reasons'')=0)\n        OR EXISTS(SELECT FROM jsonb_array_elements(obj->''reasons'') r WHERE jsonb_typeof(r) IS DISTINCT FROM ''string'' OR r#>>''{}'' !~ ''^[A-Za-z0-9_.:-]{1,128}$'')\n        OR (SELECT count(*)<>count(DISTINCT r) FROM jsonb_array_elements(obj->''reasons'') r) THEN\n        RAISE EXCEPTION ''received_register_reason_invalid'' USING ERRCODE=''23514'';\n      END IF;\n      key:=jsonb_build_array(obj->''messageIndex'',obj->''objectId'',obj->''identityAgency'',CASE WHEN obj->''objectId''=''null''::jsonb THEN obj#>''{registers,0,lineIndex}'' ELSE ''null''::jsonb END)::text;\n      IF key=ANY(object_keys) THEN RAISE EXCEPTION ''received_register_duplicate_object'' USING ERRCODE=''23514''; END IF;\n      object_keys:=array_append(object_keys,key);\n      previous_segment:=-1; position:=0;\n      FOR reg IN SELECT value FROM jsonb_array_elements(obj->''registers'') LOOP\n        position:=position+1;\n        IF jsonb_typeof(reg) IS DISTINCT FROM ''object''\n          OR NOT reg ?& ARRAY[''lineIndex'',''lineNumber'',''registerIndex'',''registerPosition'',''segmentIndex'']\n          OR reg-ARRAY[''lineIndex'',''lineNumber'',''registerIndex'',''registerPosition'',''segmentIndex''] <> ''{}''::jsonb THEN\n          RAISE EXCEPTION ''received_register_occurrence_invalid'' USING ERRCODE=''23514'';\n        END IF;\n        FOREACH key IN ARRAY ARRAY[''lineIndex'',''registerPosition'',''segmentIndex''] LOOP\n          IF jsonb_typeof(reg->key) IS DISTINCT FROM ''number'' OR coalesce(reg->>key,'''') !~ ''^[0-9]{1,4}$'' THEN\n            RAISE EXCEPTION ''received_register_index_invalid'' USING ERRCODE=''23514'';\n          END IF;\n          IF (reg->>key)::int>=8192 THEN RAISE EXCEPTION ''received_register_index_budget'' USING ERRCODE=''23514''; END IF;\n        END LOOP;\n        FOREACH key IN ARRAY ARRAY[''lineNumber'',''registerIndex''] LOOP\n          IF reg->key IS DISTINCT FROM ''null''::jsonb AND (jsonb_typeof(reg->key) IS DISTINCT FROM ''string''\n            OR length(reg->>key) NOT BETWEEN 1 AND 128 OR reg->>key<>btrim(reg->>key) OR reg->>key ~ ''[[:cntrl:]]'') THEN\n            RAISE EXCEPTION ''received_register_wire_index_invalid'' USING ERRCODE=''23514'';\n          END IF;\n        END LOOP;\n        IF (reg->>''registerPosition'')::int<>position OR (reg->>''segmentIndex'')::int<=previous_segment\n          OR jsonb_build_array(obj->''messageIndex'',reg->''lineIndex'')::text=ANY(line_ids) OR (reg->>''segmentIndex'')::int=ANY(segment_ids) THEN\n          RAISE EXCEPTION ''received_register_occurrence_conflict'' USING ERRCODE=''23514'';\n        END IF;\n        line_ids:=array_append(line_ids,jsonb_build_array(obj->''messageIndex'',reg->''lineIndex'')::text);\n        segment_ids:=array_append(segment_ids,(reg->>''segmentIndex'')::int);\n        previous_segment:=(reg->>''segmentIndex'')::int;\n      END LOOP;\n    END LOOP;\n  END IF;\n  SELECT prior.id INTO v_previous FROM gridex_received_sources.validation_assessments prior WHERE prior.source_message_id=src.source_message_id\n    AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=prior.id);\n  v_hash:=encode(sha256(convert_to(p_facts_text,''UTF8'')),''hex'');\n  INSERT INTO gridex_received_sources.validation_assessments(source_message_id,company_id,environment,source_payload_hash,previous_assessment_id,facts_text,facts_hash)\n    VALUES(src.source_message_id,p_company_id,p_environment,src.payload_hash,v_previous,p_facts_text,v_hash) RETURNING id INTO v_id;\n  RETURN jsonb_build_object(''version'',1,''assessmentId'',v_id,''companyId'',p_company_id,''environment'',p_environment,\n    ''sourceMessageId'',src.source_message_id,''sourcePayloadHash'',src.payload_hash,''factsHash'',v_hash,''sourceDisposition'',''not_established'');\nEND ","patched":"DECLARE m public.ediel_messages%rowtype;result jsonb;BEGIN\n -- Preserve the existing source-ledger -> actual-message lock order. A new\n -- invalid assessment and its delegate writes roll back in this same RPC.\n result:=gridex_received_sources.append_validation_before_unused_unh_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);\n IF p_facts_text::jsonb->>''syntaxDecision''=''accepted'' AND p_facts_text::jsonb->>''applicationDecision''=''accepted'' THEN\n  -- The protected delegate has already verified the tenant-bound retained\n  -- source/hash. A physical technical source may retain company_id NULL;\n  -- this check observes those exact same bytes without assigning a tenant.\n  SELECT s.raw_payload INTO STRICT m.raw_payload FROM gridex_received_sources.sources s WHERE s.source_message_id=p_source_message_id AND s.company_id=p_company_id AND s.environment=p_environment\n   AND s.raw_payload IS NOT NULL AND s.payload_hash=p_source_payload_hash AND encode(sha256(convert_to(s.raw_payload,''UTF8'')),''hex'')=p_source_payload_hash;\n  PERFORM gridex_ediel_ack_guide.require_unused_unh_v1(m.raw_payload,''inbound'');END IF;\n RETURN result;END ","source_line":23279,"source_statement_sha256":"41b7ea66a4f370b00cd344432aa91403c55fcf69d92f859915941d9f2dc58941","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=pg_catalog"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_company_id","p_environment","p_source_message_id","p_source_payload_hash","p_facts_text"],"proargmodes":null,"return_type":"jsonb","proretset":false,"identity_arguments":"p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text","arguments":"p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text","language":"plpgsql"}},{"signature":"gridex_received_sources.object_owner_proof_consistent(jsonb,jsonb,timestamp with time zone)","before":"bf499b92113b3e3370085d23dce02f51","after":"602be7f832a17414720cf022a4a465d5","canonical_complete":"602be7f832a17414720cf022a4a465d5","original":"\nDECLARE identity jsonb:=p_party#>''{receiver,identity}''; evidence jsonb:=p_party#>''{receiver,evidence}'';\n records jsonb:=evidence->''records''; facility jsonb:=p_party->''facility''; parties jsonb:=p_party->''parties'';\n effective jsonb:=p_business->''effectiveFrom''; commit_row jsonb; name text; stamp text; instant timestamptz;\n party_start timestamptz; party_end timestamptz; evaluated timestamptz; role_values text[]; supplied_roles text[];\n actor_count bigint; identifier_count bigint; selected_actor_id uuid; legal_id text; relation_count bigint;\n relation_id uuid; transport_actor uuid; transport_id text; minute text; market_time timestamp; expected_day text;\nBEGIN\n IF p_received IS NULL OR NOT isfinite(p_received)\n  OR p_business->>''coverage'' IS DISTINCT FROM ''committed_switch_and_supply_only''\n  OR p_business->>''sourceDisposition'' IS DISTINCT FROM ''not_established''\n  OR p_business->>''graphNamespace'' IS DISTINCT FROM ''legacy_unqualified''\n  OR p_party->>''historicalKnowledge'' IS DISTINCT FROM ''not_established''\n  OR p_party->>''authentication'' IS DISTINCT FROM ''not_assessed''\n  OR evidence->''version'' IS DISTINCT FROM ''1''::jsonb\n  OR evidence->>''owner'' IS DISTINCT FROM ''canonical-tenant-ediel-identity-v1''\n  OR evidence->>''consistency'' IS DISTINCT FROM ''independent_reads''\n  OR evidence->>''historicalKnowledge'' IS DISTINCT FROM ''not_established''\n  OR evidence->>''sourceDisposition'' IS DISTINCT FROM ''not_established''\n  OR facility->>''owner'' IS DISTINCT FROM ''selected-facility-grid-owner-v1''\n  OR facility->>''consistency'' IS DISTINCT FROM ''independent_reads''\n  OR facility->>''historicalKnowledge'' IS DISTINCT FROM ''not_established''\n  OR identity->>''companyId'' IS DISTINCT FROM p_business->>''companyId''\n  OR identity->>''environment'' IS DISTINCT FROM p_business->>''environment''\n  OR jsonb_typeof(identity->''representedByTransportAgent'') IS DISTINCT FROM ''boolean''\n  OR jsonb_typeof(identity->''roleCodes'') IS DISTINCT FROM ''array''\n  OR jsonb_typeof(parties) IS DISTINCT FROM ''object'' THEN RETURN false; END IF;\n -- PostgreSQL''s timestamp/date types own calendar parsing. Reject infinities,\n -- date-only spellings and excess fractional precision before typed equality.\n FOR stamp IN SELECT value FROM unnest(ARRAY[p_business->>''assessedAt'',p_business->>''sourceReceivedAt'',\n  p_party#>>''{source,receivedAt}'',p_party->>''assessedAt'',p_party->>''completedAt'',evidence->>''evaluatedAt'',\n  evidence->>''observedAt'',evidence->>''completedAt'',facility->>''observedAt'',facility->>''completedAt'']) value LOOP\n  IF stamp IS NULL OR stamp !~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'' THEN RETURN false; END IF;\n  instant:=stamp::timestamptz;\n  IF NOT isfinite(instant) OR instant<p_received OR instant>statement_timestamp() THEN RETURN false; END IF;\n END LOOP;\n party_start:=(p_party->>''assessedAt'')::timestamptz;party_end:=(p_party->>''completedAt'')::timestamptz;evaluated:=(evidence->>''evaluatedAt'')::timestamptz;\n IF (p_business->>''sourceReceivedAt'')::timestamptz<>p_received OR (p_party#>>''{source,receivedAt}'')::timestamptz<>p_received\n  OR party_end<party_start OR evaluated<>party_start\n  OR (evidence->>''observedAt'')::timestamptz<evaluated OR (evidence->>''completedAt'')::timestamptz<(evidence->>''observedAt'')::timestamptz\n  OR (evidence->>''completedAt'')::timestamptz>party_end\n  OR (facility->>''observedAt'')::timestamptz<party_start OR (facility->>''completedAt'')::timestamptz<(facility->>''observedAt'')::timestamptz\n  OR (facility->>''completedAt'')::timestamptz>party_end THEN RETURN false; END IF;\n FOREACH name IN ARRAY ARRAY[''legalSender'',''legalReceiver'',''transportSender'',''transportReceiver''] LOOP\n  IF jsonb_typeof(parties->name) IS DISTINCT FROM ''string'' OR length(parties->>name) NOT BETWEEN 1 AND 128\n   OR parties->>name<>btrim(parties->>name) THEN RETURN false; END IF;\n END LOOP;\n -- Same half-open tenant validity used by resolveCanonicalTenantEdielIdentity.\n IF NOT EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.tenant_ediel_profiles,records->''profiles'') r\n  WHERE r.is_enabled AND r.market=''electricity'' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to)) THEN RETURN false; END IF;\n SELECT count(DISTINCT r.actor_id),count(DISTINCT nullif(btrim(r.identifier_value),'''')),min(r.actor_id::text)::uuid,min(nullif(btrim(r.identifier_value),''''))\n INTO actor_count,identifier_count,selected_actor_id,legal_id\n FROM jsonb_populate_recordset(NULL::public.tenant_actor_identifiers,records->''identifiers'') r\n WHERE r.identifier_type=''EdielId'' AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);\n IF actor_count<>1 OR identifier_count<>1 OR selected_actor_id::text IS DISTINCT FROM identity->>''legalActorId''\n  OR legal_id IS DISTINCT FROM identity->>''legalEdielId'' OR legal_id IS DISTINCT FROM parties->>''legalReceiver'' THEN RETURN false; END IF;\n SELECT array_agg(DISTINCT btrim(r.role_code) ORDER BY btrim(r.role_code)) INTO role_values\n FROM jsonb_populate_recordset(NULL::public.tenant_actor_roles,records->''roles'') r\n WHERE r.actor_id=selected_actor_id AND nullif(btrim(r.role_code),'''') IS NOT NULL AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);\n IF EXISTS(SELECT FROM jsonb_array_elements(identity->''roleCodes'') r WHERE jsonb_typeof(r)<>''string'') THEN RETURN false; END IF;\n SELECT array_agg(DISTINCT value ORDER BY value) INTO supplied_roles FROM jsonb_array_elements_text(identity->''roleCodes'');\n IF role_values IS DISTINCT FROM supplied_roles OR NOT coalesce(''electricity_supplier''=ANY(role_values),false) THEN RETURN false; END IF;\n SELECT count(*),min(r.id::text)::uuid,min(r.counterparty_actor_id::text)::uuid INTO relation_count,relation_id,transport_actor\n FROM jsonb_populate_recordset(NULL::public.tenant_counterparty_relations,records->''relations'') r\n WHERE r.relation_type=''ediel_transport_agent'' AND r.is_enabled AND r.valid_from<=evaluated AND (r.valid_to IS NULL OR evaluated<r.valid_to);\n IF relation_count=0 THEN\n  IF identity->''representedByTransportAgent''<>''false''::jsonb OR identity->''transportRelationId'' IS DISTINCT FROM ''null''::jsonb\n   OR identity->>''transportActorId'' IS DISTINCT FROM selected_actor_id::text OR identity->>''transportEdielId'' IS DISTINCT FROM legal_id\n   OR records->''transportIdentifiers'' IS DISTINCT FROM ''[]''::jsonb THEN RETURN false; END IF;\n ELSE\n  IF relation_count<>1 OR identity->''representedByTransportAgent''<>''true''::jsonb\n   OR identity->>''transportRelationId'' IS DISTINCT FROM relation_id::text OR identity->>''transportActorId'' IS DISTINCT FROM transport_actor::text\n   OR transport_actor=selected_actor_id THEN RETURN false; END IF;\n  IF EXISTS(SELECT FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->''transportIdentifiers'') r WHERE r.is_verified IS DISTINCT FROM true) THEN RETURN false; END IF;\n  SELECT count(DISTINCT nullif(btrim(r.identifier_value),'''')),min(nullif(btrim(r.identifier_value),'''')) INTO identifier_count,transport_id\n  FROM jsonb_populate_recordset(NULL::public.platform_actor_identifiers,records->''transportIdentifiers'') r\n  WHERE r.actor_id=transport_actor AND r.identifier_type=''EdielId''\n   AND (r.valid_from IS NULL OR r.valid_from::timestamp AT TIME ZONE ''UTC''<=evaluated)\n   AND (r.valid_to IS NULL OR evaluated<r.valid_to::timestamp AT TIME ZONE ''UTC'');\n  IF identifier_count<>1 OR transport_id=legal_id OR transport_id IS DISTINCT FROM identity->>''transportEdielId'' THEN RETURN false; END IF;\n END IF;\n IF parties->>''transportReceiver'' IS DISTINCT FROM identity->>''transportEdielId''\n  OR parties->>''transportSender'' IS DISTINCT FROM parties->>''legalSender''\n  OR parties->>''legalSender'' IS DISTINCT FROM facility#>>''{gridOwner,ediel_id}''\n  OR facility#>''{gridOwner,is_active}'' IS DISTINCT FROM ''true''::jsonb OR facility#>>''{gridOwner,lifecycle_status}'' IS DISTINCT FROM ''active''\n  OR facility#>>''{gridOwner,environment}'' IS DISTINCT FROM p_business->>''environment''\n  OR (p_business->>''environment''=''production'' AND facility#>>''{gridOwner,ediel_id}'' IN (''91100'',''91109''))\n  OR facility#>>''{meteringPoint,meter_point_id}'' IS DISTINCT FROM p_business#>>''{object,objectId}''\n  OR facility#>>''{site,facility_id}'' IS DISTINCT FROM p_business#>>''{object,objectId}''\n  OR facility#>>''{meteringPoint,site_id}'' IS DISTINCT FROM facility#>>''{site,id}''\n  OR (facility#>''{meteringPoint,customer_site_id}''<>''null''::jsonb AND facility#>>''{meteringPoint,customer_site_id}'' IS DISTINCT FROM facility#>>''{site,id}'')\n  OR facility#>>''{meteringPoint,grid_owner_id}'' IS DISTINCT FROM facility#>>''{gridOwner,id}''\n  OR facility#>>''{site,grid_owner_id}'' IS DISTINCT FROM facility#>>''{gridOwner,id}'' THEN RETURN false; END IF;\n IF jsonb_typeof(effective) IS DISTINCT FROM ''object'' OR effective->>''fieldNumber'' IS DISTINCT FROM ''210''\n  OR effective->>''committedDatePrecision'' IS DISTINCT FROM ''market_calendar_day''\n  OR effective-ARRAY[''fieldNumber'',''marketMinute'',''utc'',''committedDatePrecision'']<>''{}''::jsonb THEN RETURN false; END IF;\n minute:=effective->>''marketMinute'';\n IF minute IS NULL OR minute !~ ''^[0-9]{12}$'' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;\n market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);\n IF effective->>''utc'' IS NULL OR (effective->>''utc'')::timestamptz IS DISTINCT FROM (market_time AT TIME ZONE ''Etc/GMT-1'') THEN RETURN false; END IF;\n expected_day:=to_char(market_time,''YYYY-MM-DD'');\n FOREACH name IN ARRAY ARRAY[''switch'',''supply''] LOOP\n  commit_row:=p_business#>ARRAY[''committedRecords'',name];\n  IF jsonb_typeof(commit_row) IS DISTINCT FROM ''object''\n   OR commit_row->>''id'' IS DISTINCT FROM p_business->>(CASE WHEN name=''switch'' THEN ''switchRequestId'' ELSE ''supplyPeriodId'' END)\n   OR commit_row->>''companyId'' IS DISTINCT FROM p_business->>''companyId''\n   OR commit_row->>''customerId'' IS DISTINCT FROM p_business->>''customerId''\n   OR commit_row->>''meteringPointId'' IS DISTINCT FROM p_business->>''meteringPointId''\n   OR commit_row->>''sourceMessageId'' IS DISTINCT FROM p_business->>''sourceMessageId''\n   OR commit_row->>''status'' IS DISTINCT FROM (CASE WHEN name=''switch'' THEN ''accepted'' ELSE ''confirmed_by_grid_owner'' END)\n   OR commit_row->>(CASE WHEN name=''switch'' THEN ''confirmedStartDate'' ELSE ''startDate'' END) IS DISTINCT FROM expected_day\n   OR (name=''switch'' AND commit_row->>''siteId'' IS DISTINCT FROM p_business->>''siteId'') THEN RETURN false; END IF;\n END LOOP;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;\nEND ","patched":"\nDECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;legacy_shape jsonb;\nBEGIN\n IF p_business#>>''{effectiveFrom,committedDatePrecision}'' IS DISTINCT FROM ''market_minute'' THEN RETURN gridex_received_sources.object_owner_before_normal_minute_v1(p_party,p_business,p_received);END IF;\n SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=(p_business->>''supplyPeriodId'')::uuid AND company_id=(p_business->>''companyId'')::uuid AND source_message_id=(p_business->>''sourceMessageId'')::uuid AND switch_id=(p_business->>''switchRequestId'')::uuid;\n IF NOT FOUND OR p_business->>''owner'' IS DISTINCT FROM ''inbound-z04-switch-confirmation-v1'' OR p_business->>''sourcePayloadHash'' IS DISTINCT FROM (SELECT payload_hash FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=proof.company_id)\n  OR p_business#>>''{object,objectId}'' IS DISTINCT FROM proof.source_object->>''point'' OR p_business#>>''{object,identityAgency}'' IS DISTINCT FROM proof.source_object->>''identityAgency''\n  OR p_business->>''customerId'' IS DISTINCT FROM proof.confirmed_period->>''customer_id'' OR p_business->>''meteringPointId'' IS DISTINCT FROM proof.confirmed_period->>''metering_point_id'' OR p_business->>''siteId'' IS DISTINCT FROM coalesce(proof.confirmed_switch->>''site_id'',proof.confirmed_switch->>''customer_site_id'')\n  OR p_business#>>''{effectiveFrom,marketMinute}'' IS DISTINCT FROM proof.source_object->>''start'' OR (p_business#>>''{effectiveFrom,utc}'')::timestamptz IS DISTINCT FROM proof.market_st$ops_compact_part_4$) ON CONFLICT(ordinal) DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops_api_atomic_transport_bb0bd0ce.payload_parts WHERE ordinal=4 AND octet_length(convert_to(payload,'UTF8'))=80547 AND encode(sha256(convert_to(payload,'UTF8')),'hex')='1f375fd1052f325b5a2e23f1c0a87d7a5c4c0c39c84b01ad6afa154865ecafc7') THEN RAISE EXCEPTION 'ops_compact_transport_stage_postcheck_failed'; END IF;
